package local.morph.iptvcheck;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import android.graphics.drawable.*;import java.lang.reflect.*;import org.json.*;
public class AdhanInstrumentation extends Instrumentation {
 Activity player;Object adhan;Class<?> type;
 Object field(Object owner,String name)throws Exception{Field f=owner.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(owner);}
 Object invoke(String method,Class<?>[] types,Object... args)throws Exception{Method m=type.getDeclaredMethod(method,types);m.setAccessible(true);return m.invoke(adhan,args);}
 void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
 @Override public void onCreate(Bundle args){super.onCreate(args);start();}
 @Override public void onStart(){Bundle result=new Bundle();try{
  getTargetContext().getSharedPreferences("tvmorph-ui",0).edit().putString("language","en").putBoolean("systemVodPlayer",false).commit();type=Class.forName("local.tvmorph.tv.AdhanPlayback",true,getTargetContext().getClassLoader());Method get=type.getDeclaredMethod("get",Context.class);get.setAccessible(true);runOnMainSync(()->{try{adhan=get.invoke(null,getTargetContext());}catch(Exception e){throw new RuntimeException(e);}});
  player=startActivitySync(new Intent().setClassName(getTargetContext().getPackageName(),"local.tvmorph.tv.PlayerActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK).putExtra("url","http://10.0.2.2:8766/layout.mp4").putExtra("name","Owned Adhan background verification").putExtra("itemKind","vod").putExtra("itemId","local-adhan-background-check").putExtra("live",false));long until=SystemClock.uptimeMillis()+25000;while(SystemClock.uptimeMillis()<until&&!Boolean.TRUE.equals(field(player,"prepared")))Thread.sleep(50);check(Boolean.TRUE.equals(field(player,"prepared")),"Owned video prepares");
  JSONObject schedule=new JSONObject().put("enabled",true).put("voice","egypt").put("volume",0).put("items",new JSONArray().put(new JSONObject().put("name","Maghrib").put("adhan",true).put("at",System.currentTimeMillis()+1500)));invoke("update",new Class<?>[]{String.class},schedule.toString());Dialog dialog=null;until=SystemClock.uptimeMillis()+10000;while(SystemClock.uptimeMillis()<until){dialog=(Dialog)field(adhan,"dialog");if(dialog!=null&&dialog.isShowing())break;Thread.sleep(100);}check(dialog!=null&&dialog.isShowing(),"Adhan overlay opens above video");
  final Dialog visible=dialog;ViewGroup content=(ViewGroup)dialog.findViewById(android.R.id.content);FrameLayout root=(FrameLayout)content.getChildAt(0);ImageView image=(ImageView)root.getChildAt(0);check(image.getDrawable() instanceof BitmapDrawable,"Bundled mosque image is decoded");final android.graphics.drawable.Drawable original=image.getDrawable();
  for(int i=0;i<6;i++){runOnMainSync(()->{try{Method update=player.getClass().getDeclaredMethod("update");update.setAccessible(true);update.invoke(player);((View)field(player,"loading")).setVisibility(View.VISIBLE);}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(250);check(visible.isShowing()&&image.getDrawable()==original,"Same mosque background remains visible during player refresh/buffering");}
  android.graphics.Bitmap capture=getUiAutomation().takeScreenshot();if(capture!=null){java.io.File file=new java.io.File(getTargetContext().getExternalFilesDir(null),"adhan-local.png");try(java.io.FileOutputStream out=new java.io.FileOutputStream(file)){capture.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}capture.recycle();}
  invoke("cancel",new Class<?>[]{});Thread.sleep(300);check(!visible.isShowing(),"Stop removes the overlay only at explicit cancellation");runOnMainSync(()->player.finish());result.putString("result","PASS: exact bundled mosque background remains on screen throughout Adhan over a playing video and repeated buffering/UI updates; explicit stop closes it.");finish(Activity.RESULT_OK,result);
 }catch(Throwable e){result.putString("error",android.util.Log.getStackTraceString(e));try{if(adhan!=null)invoke("cancel",new Class<?>[]{});}catch(Exception ignored){}if(player!=null)runOnMainSync(()->player.finish());finish(Activity.RESULT_CANCELED,result);}}
}
